import sys

def min_rows_for_mirroring(n, m, matrix):
    def is_symmetric(matrix, x):
        for i in range(x):
            for j in range(m):
                if matrix[i][j] != matrix[2 * x - i - 1][j]:
                    return False
        return True

    for x in range(1, n + 1):
        if is_symmetric(matrix, x):
            return x
    return n

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])
    matrix = []
    index = 2
    for i in range(n):
        row = list(map(int, data[index:index + m]))
        matrix.append(row)
        index += m

    result = min_rows_for_mirroring(n, m, matrix)
    print(result)

if __name__ == "__main__":
    main()
